lign-items:center;gap:4px;flex-wrap:wrap}\n.rl .lnk{margin-left:auto}\n.where{font-size:11px;color:var(--ink);line-height:1.35}\n.bar{display:flex;gap:2px;height:5px}\n.bar i{flex:1;border-radius:3px;background:var(--line)}\n.bar i.done{background:var(--accent)}\n.bar i.wait{background:var(--accent-alt)}\n.bar i.blocked,.bar i.failed,.bar i.skipped{background:var(--muted);opacity:.55}\n.runsplit{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.stepnav{flex:none;display:flex;gap:4px;overflow-x:auto;padding-bottom:2px}\n.sn{flex:none;display:flex;align-items:center;gap:5px;max-width:150px;height:26px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:transparent;color:var(--ink);font:inherit;cursor:pointer}\n.sn.on{border-color:var(--accent);background:var(--soft);font-weight:700}\n.sn .no{color:var(--muted)}\n.sn .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.sn .mk{margin-left:auto;font-weight:700}\n.sn.wait .mk{color:var(--accent-alt)}\n.sn.done .mk{color:var(--accent)}\n.card[data-size=\"3x3\"] .sn .nm{display:none}\n.card[data-size=\"3x3\"] .sn{padding:0 7px}\n.card[data-size=\"3x6\"] .stepnav{flex-direction:column;overflow-x:hidden;overflow-y:auto;max-height:40%}\n.card[data-size=\"3x6\"] .sn{max-width:none}\n.card[data-size=\"6x6\"] .runsplit{flex-direction:row}\n.card[data-size=\"6x6\"] .stepnav{flex-direction:column;width:122px;overflow-x:hidden;overflow-y:auto;padding:0}\n.card[data-size=\"6x6\"] .sn{max-width:none}\n.stepdetail{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:7px;padding-right:2px}\n.dh{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.dt{flex:1;min-width:60px}\n.badge{font-size:11px;border:1px solid var(--line);border-radius:999px;padding:0 7px;white-space:nowrap}\n.badge.done{border-color:var(--accent);color:var(--accent)}\n.badge.wait{border-color:var(--accent-alt);color:var(--accent-alt)}\n.req{border-left:3px solid var(--accent);background:var(--soft);border-radius:6px;padding:4px 8px;white-space:pre-wrap;overflow:auto;max-height:90px}\n.req .lab{display:block;font-size:11px;color:var(--muted);font-weight:600}\n.info{border:1px dashed var(--line);border-radius:8px;padding:4px 8px;color:var(--ink)}\n.info.bad{border-style:solid;border-color:var(--accent-alt)}\n.dacts{display:flex;flex-wrap:wrap;gap:6px}\n.projs{display:flex;flex-direction:column;gap:6px}\n.proj{border:1px solid var(--line);border-radius:10px;padding:6px;display:flex;flex-direction:column;gap:4px;background:var(--soft)}\n.pname{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pf{display:flex;flex-direction:column;gap:5px}\n.card[data-size=\"6x3\"] .pf{flex-direction:row}\n.fl{display:flex;flex-direction:column;gap:2px;flex:1}\n.fl>span{font-size:11px;color:var(--muted)}\n.mlist{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:8px;padding:0 8px}\n.mrow{padding:4px 0;border-top:1px solid var(--line)}\n.mrow:first-child{border-top:0}\n.ms{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.mm{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.draft{flex:1;min-height:56px;white-space:pre-wrap}\n.sec{display:flex}\n.morebtn{display:none}\n.card[data-size=\"3x3\"] .morebtn{display:block;padding:0 8px}\n.card[data-size=\"3x3\"] .sec{display:none}\n.card[data-size=\"3x3\"] .sec.open{display:flex}\n.hrow{display:flex;flex-direction:column;align-items:flex-start;text-align:left;width:100%;border:1px solid var(--line);border-radius:10px;background:transparent;color:var(--ink);font:inherit;padding:6px 8px;cursor:pointer}\n.hrow.on{border-color:var(--accent);background:var(--soft)}\n.hr1{font-weight:700}\n.empty{margin:auto;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;color:var(--muted);padding:6px}\n.empty b{color:var(--ink);font-size:13px}\n.srow{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:10px;padding:6px 8px;background:var(--soft)}\n.card[data-size=\"3x3\"] .srow,.card[data-size=\"3x6\"] .srow{flex-direction:column;align-items:stretch}\n.smain{flex:1;display:flex;flex-direction:column;gap:2px}\n.st1{display:flex;align-items:center;gap:6px}\n.st1 .no{color:var(--muted)}\n.st1 b{flex:1}\n.kd{font-size:11px;color:var(--muted);white-space:nowrap}\n.sreq{color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.sbt{display:flex;gap:4px;flex:none}\n.card[data-size=\"3x3\"] .sbt,.card[data-size=\"3x6\"] .sbt{justify-content:flex-end}\n";
const KIND_NAME={calendar:'日历',mail:'邮件',work:'项目进展与问题',manual:'手动步骤',draft:'生成草稿'};
const KIND_HINT={
calendar:'读取所选日期范围内的日程。日历读取尚未接入：运行时会标明未接入，不会编造日程，可手动补充要点。',
mail:'读取所选范围内的邮件元数据（发件人、主题、时间，不含正文）。需要平台先为本卡片连接邮箱，否则标明未接入。',
work:'按所选项目逐个填写本期进展和问题。',
manual:'需要你自己填写要点的步骤。',
draft:'把前面各步骤的内容按固定模板拼成周报草稿，只给你审阅，不会发送。'};
const STATUS_NAME={pending:'待运行',wait:'等你填写',done:'已完成',blocked:'未接入',failed:'读取失败',skipped:'已跳过'};
const STATUS_MARK={pending:'○',wait:'✎',done:'✓',blocked:'⊘',failed:'!',skipped:'–'};
const SETTLED=['done','blocked','failed','skipped'];
const PRESETS=[['week','本周'],['last','上周'],['last7','近7天'],['custom','自定义']];
const KIND_ORDER=['calendar','mail','work','manual','draft'];
const DEFAULT_STEPS=[
{id:'s-cal',kind:'calendar',title:'查看日历',req:''},
{id:'s-mail',kind:'mail',title:'查看邮件',req:''},
{id:'s-work',kind:'work',title:'整理项目进展和问题',req:''},
{id:'s-draft',kind:'draft',title:'撰写周报',req:''}];

function initialize(s){
  if(s&&Array.isArray(s.steps))return s;
  const o=Object.assign({},s||{});
  o.steps=DEFAULT_STEPS.map(x=>Object.assign({},x));
  return o;
}
function norm(s){
  const o=Object.assign({},s||{});
  o.projects=Array.isArray(o.projects)?o.projects:[];
  o.steps=Array.isArray(o.steps)?o.steps:[];
  o.runs=Array.isArray(o.runs)?o.runs:[];
  o.sel=Object.assign({preset:'week',from:'',to:'',projectIds:[]},o.sel||{});
  if(!Array.isArray(o.sel.projectIds))o.sel.projectIds=[];
  return o;
}
function clone(x){return JSON.parse(JSON.stringify(x));}
function pad(n){return n<10?'0'+n:''+n;}
function parseDay(d){const a=String(d).split('-').map(Number);return new Date(a[0],a[1]-1,a[2]);}
function fmtDay(t){return t.getFullYear()+'-'+pad(t.getMonth()+1)+'-'+pad(t.getDate());}
function addDays(d,n){const t=parseDay(d);t.setDate(t.getDate()+n);return fmtDay(t);}
function mondayOf(d){const t=parseDay(d);return addDays(d,-((t.getDay()+6)%7));}
function stamp(){const t=new Date();return fmtDay(t)+' '+pad(t.getHours())+':'+pad(t.getMinutes());}
function rangeOf(sel,today){
  const p=sel.preset;
  if(p==='last7')return{from:addDays(today,-6),to:today};
  if(p==='last'){const m=addDays(mondayOf(today),-7);return{from:m,to:addDays(m,6)};}
  if(p==='custom')return{from:sel.from||'',to:sel.to||''};
  const m=mondayOf(today);return{from:m,to:addDays(m,6)};
}
function cnNum(n){return['','一','二','三','四','五','六','七','八','九','十'][n]||String(n);}

function settle(r){
  for(const step of r.steps){
    const cur=r.st[step.id]||(r.st[step.id]={status:'pending'});
    if(SETTLED.indexOf(cur.status)>=0)continue;
    if(step.kind==='calendar'){
      r.st[step.id]={status:'blocked',short:'日历未接入，未读取',msg:'日历读取尚未接入，没有读取你的日程。可以把本期日程要点手动写在下面。',at:stamp()};
      continue;
    }
    if(step.kind==='mail'){r.status='active';r.cursor=step.id;return'mail';}
    if(step.kind==='work'||step.kind==='manual'){r.status='active';cur.status='wait';r.cursor=step.id;return'wait';}
    if(step.kind==='draft'){
      r.draft=compile(r);
      r.st[step.id]={status:'done',msg:'按固定模板拼接你填写的内容，不是 AI 撰写；草稿只供审阅，未发送。',at:stamp()};
    }
  }
  r.cursor='';
  if(r.status!=='reviewed')r.status='review';
  return'end';
}

function compile(r){
  const L=['周报（'+r.from+' 至 '+r.to+'）',''];
  let n=0;
  for(const step of r.steps){
    if(step.kind==='draft')continue;
    n++;
    L.push(cnNum(n)+'、'+step.title);
    const st=r.st[step.id]||{};
    const note=String(r.notes[step.id]||'').trim();
    const miss=(st.status==='blocked'||st.status==='failed')?'（'+(st.short||'未读取')+'，待补充）':'（待补充）';
    if(step.kind==='work'){
      if(!r.projects.length)L.push('（未选择项目）');
      for(const p of r.projects){
        const w=r.work[p.id]||{};
        L.push('【'+p.name+'】');
        L.push('进展：'+(String(w.p||'').trim()||'（待补充）'));
        L.push('问题：'+(String(w.i||'').trim()||'（待补充）'));
      }
    }else{
      const m=r.mail[step.id];
      if(step.kind==='mail'&&m&&m.ok)L.push('读取到邮件元数据 '+m.n+' 封（仅发件人、主题、时间）。');
      L.push(note||miss);
    }
    L.push('');
  }
  return L.join('\n').trim();
}

function cut(v,n){const s=String(v==null?'':v);return s.length>n?s.slice(0,n)+'…':s;}
async function fetchMail(host,from,to){
  let res;
  try{res=await host.fetchData('connected.mail.message-list');}
  catch(e){
    const t=String((e&&(e.errorCode||e.code))||'')+' '+String((e&&e.message)||'');
    if(t.indexOf('permission_denied')>=0)return{ok:false,status:'blocked',short:'邮箱未连接，未读取',msg:'邮箱未连接：请先在平台为本卡片连接邮箱，再点「重试读取」。没有读取到任何邮件。'};
    return{ok:false,status:'failed',short:'邮件读取失败',msg:'读取邮件失败：'+cut((e&&e.message)||'请稍后重试',60)+'。已保留原有内容，可重试。'};
  }
  if(!res||res.status!=='ok'){
    const code=res&&(res.errorCode||res.status);
    if(code==='permission_denied')return{ok:false,status:'blocked',short:'邮箱未连接，未读取',msg:'邮箱未连接：请先在平台为本卡片连接邮箱，再点「重试读取」。没有读取到任何邮件。'};
    return{ok:false,status:'failed',short:'邮件读取失败',msg:'读取邮件失败'+(code?'（'+code+'）':'')+'，可重试。'};
  }
  const d=res.data;
  const arr=Array.isArray(d)?d:((d&&(d.messages||d.items||d.list))||[]);
  if(!Array.isArray(arr))return{ok:false,status:'failed',short:'邮件读取失败',msg:'邮件数据格式无法识别，可重试。'};
  const all=arr.map(it=>{
    const o=it||{};
    return{f:cut(o.from||o.sender||o.from_name||'',60),s:cut(o.subject||o.title||'（无主题）',80),d:cut(o.date||o.received_at||o.receivedAt||o.sent_at||o.time||'',32)};
  });
  let known=0;
  const kept=all.filter(m=>{
    const ts=Date.parse(m.d);
    if(isNaN(ts))return false;
    known++;
    const dd=fmtDay(new Date(ts));
    return dd>=from&&dd<=to;
  });
  const filtered=known>0;
  const items=filtered?kept:all;
  return{ok:true,status:'done',n:items.length,total:all.length,filtered:filtered,items:items,
    msg:filtered?'读取到 '+items.length+' 封范围内的邮件元数据（平台共返回 '+all.length+' 封）。':'平台返回 '+all.length+' 封邮件元数据，数据没有可识别的日期，未按日期范围过滤。'};
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,uid,day,host}=ctx;
  const S=norm(state);
  const today=day();
  if(!ui.drafts)ui.drafts={};
  if(!ui.tab)ui.tab='prep';

  function h(tag,attrs,...kids){
    const flat=[];
    (function add(k){
      if(k===null||k===undefined||k===false)return;
      if(Array.isArray(k)){k.forEach(add);return;}
      flat.push(typeof k==='number'?String(k):k);
    })(kids);
    return el(tag,attrs||{},...flat);
  }
  async function mutate(fn){
    ui.err='';
    try{await update(s=>fn(clone(norm(s))));return true;}
    catch(e){ui.err='保存失败：'+cut((e&&e.message)||'请重试',50);redraw();return false;}
  }
  async function mutRun(id,fn){
    let reached=false;
    const ok=await mutate(s=>{
      const x=s.runs.find(q=>q.id===id);
      if(!x)return s;
      const b=x.status;
      fn(x,s);
      if(b!=='review'&&x.status==='review')reached=true;
      return s;
    });
    if(ok&&reached){ui.tab='report';ui.hist=false;ui.runId=id;redraw();}
    return ok;
  }
  function curRun(){return S.runs.find(r=>r.id===ui.runId)||S.runs[0]||null;}
  function selectedIds(){return S.sel.projectIds.filter(id=>S.projects.some(p=>p.id===id));}
  function curRange(){
    const sel=S.sel;
    if(sel.preset==='custom')return{from:ui.cf!==undefined?ui.cf:sel.from,to:ui.ct!==undefined?ui.ct:sel.to};
    return rangeOf(sel,today);
  }
  function startErr(){
    const rg=curRange();
    if(!S.steps.length)return'还没有步骤，先到「步骤」页添加。';
    if(!rg.from||!rg.to)return'请选择起止日期。';
    if(rg.from>rg.to)return'开始日期不能晚于结束日期。';
    if(S.steps.some(s=>s.kind==='work')&&!selectedIds().length)return'请先选择（或添加）至少一个项目。';
    return'';
  }
  function where(r){
    if(r.status==='reviewed')return'已标记审阅（未发送）';
    const idx=r.steps.findIndex(s=>SETTLED.indexOf((r.st[s.id]||{}).status)<0);
    if(idx<0)return r.steps.some(s=>s.kind==='draft')?'草稿已生成，待你审阅（未发送）':'所有步骤已处理';
    const stp=r.steps[idx];
    const x=(r.st[stp.id]||{}).status;
    const lbl=ui.busy===stp.id?'（读取中）':(x==='wait'?'（等你填写）':'');
    return'做到第 '+(idx+1)+'/'+r.steps.length+' 步 · '+stp.title+lbl;
  }
  function activeStepId(r){
    const a=r.steps.find(s=>SETTLED.indexOf((r.st[s.id]||{}).status)<0);
    return a?a.id:(r.steps[r.steps.length-1]||{}).id;
  }

  /* 动作 */
  function setPreset(k){
    mutate(s=>{
      const prev=rangeOf(s.sel,today);
      s.sel.preset=k;
      if(k==='custom'){
        const f=ui.cf!==undefined?ui.cf:(s.sel.from||prev.from);
        const t=ui.ct!==undefined?ui.ct:(s.sel.to||prev.to);
        s.sel.from=f;s.sel.to=t;ui.cf=f;ui.ct=t;
      }
      return s;
    });
  }
  function toggleProject(id){
    mutate(s=>{
      const a=s.sel.projectIds;
      const i=a.indexOf(id);
