  async function doMail(runId,stepId,from,to){
    ui.busy=stepId;redraw();
    const res=await fetchMail(host,from,to);
    ui.busy='';
    await mutRun(runId,x=>{
      x.st[stepId]=res.ok?{status:'done',msg:res.msg,at:stamp()}:{status:res.status,short:res.short,msg:res.msg,at:stamp()};
      if(res.ok)x.mail[stepId]={ok:true,n:res.n,total:res.total,filtered:res.filtered,items:res.items};
      else delete x.mail[stepId];
      settle(x);
    });
  }
  async function flow(runId,from,to){
    for(let i=0;i<12;i++){
      let need='';
      await mutRun(runId,x=>{need=settle(x)==='mail'?x.cursor:'';});
      if(!need)break;
      await doMail(runId,need,from,to);
    }
  }
  async function startRun(){
    const msg=startErr();
    if(msg){ui.prepErr=msg;redraw();return;}
    if(ui.starting)return;
    ui.starting=true;ui.prepErr='';
    const rg=curRange();
    const id=uid();
    const prev={tab:ui.tab,runId:ui.runId,sel:ui.selStep};
    ui.runId=id;ui.tab='run';ui.selStep='';ui.hist=false;
    const ok=await mutate(s=>{
      if(s.sel.preset==='custom'){s.sel.from=rg.from;s.sel.to=rg.to;}
      const ids=s.sel.projectIds;
      const run={id:id,startedAt:stamp(),from:rg.from,to:rg.to,
        projects:s.projects.filter(p=>ids.indexOf(p.id)>=0).map(p=>({id:p.id,name:p.name})),
        steps:s.steps.map(x=>({id:x.id,kind:x.kind,title:x.title,req:x.req||''})),
        st:{},notes:{},work:{},mail:{},draft:'',status:'active',cursor:''};
      settle(run);
      s.runs.unshift(run);
      return s;
    });
    ui.starting=false;
    if(!ok){ui.tab=prev.tab;ui.runId=prev.runId;ui.selStep=prev.sel;redraw();return;}
    await flow(id,rg.from,rg.to);
  }


  async function saveStep(r,step,mode){
    const keys=[];
    const ok=await mutRun(r.id,x=>{
      if(step.kind==='work'){
        x.projects.forEach(p=>{
          const kp='w:'+x.id+':'+p.id+':p',ki='w:'+x.id+':'+p.id+':i';
          const w=x.work[p.id]=x.work[p.id]||{p:'',i:''};
          if(ui.drafts[kp]!==undefined){w.p=ui.drafts[kp];keys.push(kp);}
          if(ui.drafts[ki]!==undefined){w.i=ui.drafts[ki];keys.push(ki);}
        });
      }else{
        const k='n:'+x.id+':'+step.id;
        if(ui.drafts[k]!==undefined){x.notes[step.id]=ui.drafts[k];keys.push(k);}
      }
      if(mode==='done')x.st[step.id]={status:'done',at:stamp()};
      if(mode==='skip')x.st[step.id]={status:'skipped',at:stamp()};
      if(mode==='reopen')x.st[step.id]={status:'pending'};
      settle(x);
    });
    if(ok)keys.forEach(k=>{delete ui.drafts[k];});
  }
  async function retryMail(r,step){
    await mutRun(r.id,x=>{x.st[step.id]={status:'pending'};x.status='active';});
    await doMail(r.id,step.id,r.from,r.to);
  }

