    const k=[];
    k.push(h('div',{class:'dh'},h('span',{class:'mut'},'第 '+(idx+1)+' 步'),h('b',{class:'dt'},step.title),h('span',{class:'badge '+st.status},STATUS_MARK[st.status]+' '+(busy?'读取中…':STATUS_NAME[st.status]))));
