    if(st.status==='skipped'&&!off)acts.push(h('button',{type:'button',class:'btn',onclick:()=>saveStep(r,step,'reopen')},'取消跳过'));
    if(acts.length)k.push(h('div',{class:'dacts'},acts));
    return h('div',{class:'stepdetail'},k);
  }

